1	package org.tasktelemetry.transport.crossprocess;
2	
3	import java.io.BufferedReader;
4	import java.io.BufferedWriter;
5	import java.io.IOException;
6	import java.io.InputStreamReader;
7	import java.io.OutputStreamWriter;
8	import java.net.ServerSocket;
9	import java.net.Socket;
10	import java.net.SocketException;
11	import java.nio.charset.StandardCharsets;
12	import java.util.concurrent.CopyOnWriteArrayList;
13	import java.util.concurrent.atomic.AtomicInteger;
14	import java.util.logging.Level;
15	import java.util.logging.Logger;
16	
17	/**
18	 * Localhost TCP relay that forwards text lines among all connected clients.
19	 *
20	 * <p>Each connected client may both send and receive lines. When a line arrives
21	 * from one connection it is broadcast to all <em>other</em> currently-connected
22	 * clients. The hub is deliberately line-oriented and serializer-agnostic: it
23	 * never deserializes the content, it just relays raw text.
24	 *
25	 * <h2>Threading model</h2>
26	 * <ul>
27	 *   <li>One daemon accept-loop thread ({@code task-telemetry-crossprocess-hub-accept-N}).</li>
28	 *   <li>One daemon reader thread per accepted connection
29	 *       ({@code task-telemetry-crossprocess-hub-reader-N}).</li>
30	 * </ul>
31	 *
32	 * <h2>Fault isolation</h2>
33	 * An I/O failure on one connection drops only that connection; other connections
34	 * are unaffected. Events published while a client is not connected are not
35	 * delivered to it (best-effort, live, no replay).
36	 *
37	 * <h2>Usage</h2>
38	 * <pre>{@code
39	 * try (CrossProcessTaskHub hub = new CrossProcessTaskHub(0)) {
40	 *     int actualPort = hub.port();
41	 *     // connect SocketTaskTransport instances to localhost:actualPort
42	 * }
43	 * }</pre>
44	 */
45	public final class CrossProcessTaskHub implements AutoCloseable {
46	
47	    private static final Logger LOGGER = Logger.getLogger(CrossProcessTaskHub.class.getName());
48	    private static final String THREAD_PREFIX = "task-telemetry-crossprocess-hub-";
49	
50	    private static final AtomicInteger HUB_COUNTER = new AtomicInteger(1);
51	
52	    private final ServerSocket serverSocket;
53	    private final CopyOnWriteArrayList<ClientConnection> connections = new CopyOnWriteArrayList<>();
54	    private final String hubName;
55	
56	    /**
57	     * Creates a hub bound to the given port.
58	     * Use {@code port = 0} to let the OS assign an ephemeral port; read the
59	     * actual port back via {@link #port()}.
60	     *
61	     * @param port the TCP port to bind; 0 for ephemeral
62	     * @throws IOException if the server socket cannot be created
63	     */
64	    public CrossProcessTaskHub(int port) throws IOException {
65	        this.hubName = String.valueOf(HUB_COUNTER.getAndIncrement());
66	        this.serverSocket = new ServerSocket(port);
67	        startAcceptLoop();
68	    }
69	
70	    /**
71	     * Returns the actual TCP port this hub is listening on.
72	     *
73	     * @return the bound port
74	     */
75	    public int port() {
76	        return serverSocket.getLocalPort();
77	    }
78	
79	    /**
80	     * Stops accepting new connections, closes the server socket, and closes all
81	     * existing client connections.
82	     */
83	    @Override
84	    public void close() {
85	        try {
86	            serverSocket.close();
87	        } catch (IOException ex) {
88	            LOGGER.log(Level.WARNING, "task-telemetry - hub " + hubName + ": error closing server socket", ex);
89	        }
90	
91	        for (ClientConnection connection : connections) {
92	            connection.close();
93	        }
94	        connections.clear();
95	    }
96	
97	    private void startAcceptLoop() {
98	        Thread acceptThread = new Thread(this::acceptLoop, THREAD_PREFIX + "accept-" + hubName);
99	        acceptThread.setDaemon(true);
100	        acceptThread.start();
101	    }
102	
103	    private void acceptLoop() {
104	        while (!serverSocket.isClosed()) {
105	            try {
106	                Socket socket = serverSocket.accept();
107	                ClientConnection connection = new ClientConnection(socket);
108	                connections.add(connection);
109	                connection.startReaderThread();
110	            } catch (SocketException ex) {
111	                // Normal shutdown: serverSocket.close() triggers this.
112	                break;
113	            } catch (IOException ex) {
114	                LOGGER.log(Level.WARNING, "task-telemetry - hub " + hubName + ": accept error", ex);
115	            }
116	        }
117	    }
118	
119	    private void broadcast(String line, ClientConnection sender) {
120	        for (ClientConnection connection : connections) {
121	            if (connection != sender) {
122	                connection.send(line);
123	            }
124	        }
125	    }
126	
127	    private void removeConnection(ClientConnection connection) {
128	        connections.remove(connection);
129	    }
130	
131	    // --- Inner class ---
132	
133	    private final class ClientConnection {
134	
135	        private static final AtomicInteger READER_COUNTER = new AtomicInteger(1);
136	
137	        private final Socket socket;
138	        private final BufferedWriter writer;
139	
140	        ClientConnection(Socket socket) throws IOException {
141	            this.socket = socket;
142	            this.writer = new BufferedWriter(
143	                    new OutputStreamWriter(socket.getOutputStream(), StandardCharsets.UTF_8));
144	        }
145	
146	        void startReaderThread() {
147	            Thread readerThread = new Thread(this::readLoop,
148	                    THREAD_PREFIX + "reader-" + READER_COUNTER.getAndIncrement());
149	            readerThread.setDaemon(true);
150	            readerThread.start();
151	        }
152	
153	        private void readLoop() {
154	            try (BufferedReader reader = new BufferedReader(
155	                    new InputStreamReader(socket.getInputStream(), StandardCharsets.UTF_8))) {
156	                String line;
157	                while ((line = reader.readLine()) != null) {
158	                    broadcast(line, this);
159	                }
160	            } catch (SocketException ex) {
161	                // Normal: socket was closed (either by close() or by the remote side).
162	            } catch (IOException ex) {
163	                LOGGER.log(Level.WARNING, "task-telemetry - hub " + hubName + ": read error", ex);
164	            } finally {
165	                removeConnection(this);
166	                close();
167	            }
168	        }
169	
170	        synchronized void send(String line) {
171	            try {
172	                writer.write(line);
173	                writer.newLine();
174	                writer.flush();
175	            } catch (IOException ex) {
176	                // Connection is broken — drop it so other clients are not affected.
177	                LOGGER.log(Level.WARNING, "task-telemetry - hub " + hubName + ": write error, dropping connection", ex);
178	                removeConnection(this);
179	                close();
180	            }
181	        }
182	
183	        void close() {
184	            try {
185	                socket.close();
186	            } catch (IOException ex) {
187	                LOGGER.log(Level.FINE, "task-telemetry - hub " + hubName + ": error closing connection socket", ex);
188	            }
189	        }
190	    }
191	}
